model:
rachana: 1
sutra: credit-limit
version: 2
description: 
match: { kind: credit-limit, priority: 10 }
title: { pill: "Exposure and capital · Credit limit", id: "$.LIMIT_ID" }
strip:
  - { label: "Counterparty", bind: "$.COUNTERPARTY_NAME" }
  - { label: "Measure", bind: "$.MEASURE" }
  - { label: "Limit", bind: "$.LIMIT", fmt: "compact" }
  - { label: "Used", bind: "$.USED", fmt: "compact" }
  - { label: "Utilisation", bind: "$.UTILISATION", fmt: "pct0", emphasis: true }
  - { label: "Status", bind: "$.STATUS", tone: "status" }
panels:
  - id: buckets
    kind: table
    title: "By tenor bucket"
    key: "F2"
    form: { title: "Bucket limits", key: "bucket", edit: "cells", fields: [{ id: "bucket", label: "Bucket", bind: "BUCKET", readonly: true, reason: "the tenor buckets are set by the limits policy" }, { id: "limit", label: "Limit", bind: "LIMIT", type: "number", min: 0, required: true, fmt: "amount0" }, { id: "used", label: "Used", bind: "USED", type: "number", readonly: true, reason: "measured by the exposure engine" }], rules: [{ rule: "limit >= used", fields: ["limit"], message: "The new limit is below what's already used: raise it, or ask the owner first." }, { rule: "limit <= used * 3", severity: "warn", fields: ["limit"], message: "More than three times what's used: the credit committee reviews it." }] }
    rows: "$.BUCKETS"
    columns:
      - { label: "Bucket", bind: "@.BUCKET" }
      - { label: "Limit", bind: "@.LIMIT", fmt: "compact" }
      - { label: "Used", bind: "@.USED", fmt: "compact" }
      - { label: "Utilisation", bind: "@.UTILISATION", fmt: "pct0" }
  - id: util
    kind: hbar
    title: "Utilisation"
    area: right
    rows: "$.BUCKETS"
    label: "BUCKET"
    value: "UTILISATION"
    fmt: "pct0"
  - id: checks
    kind: kv
    title: "Checks: headroom and utilisation"
    area: right
    columns:
      - { label: "Headroom", bind: "$.LIMIT - $.USED", fmt: "compact", tone: "sign" }
      - { label: "Utilisation (check: used / limit)", bind: "$.LIMIT > 0 ? $.USED / $.LIMIT : null", fmt: "pct0" }
      - { label: "Utilisation difference", bind: "$.LIMIT > 0 ? $.USED / $.LIMIT - $.UTILISATION : null", fmt: "pct2" }
  - id: built
    kind: provenance
    title: "How this view was built"
  - id: refs
    kind: links
    title: "Linked entities"
    code: "REFS"
    area: right
keys: { F7: "link($.COUNTERPARTY, 'counterparty')", F8: "impact", F9: "raw" }
